45	export const MediaViewerModalContent: FC<Props> = ({ payload }) => {
46	  const [showControls, setShowControls] = useState(true);
47	  const [currentIndex, setCurrentIndex] = useState(0);
48	  const localUriByEventIdRef = useRef<Map<string, string | null>>(new Map());
49	  const controlsAnimation = useRef(
50	    animateParallel(
51	      { translateY: [-120, 0], opacity: [0, 1] },
52	      { duration: 280 },
53	    ),
54	  ).current;
55	  const setPayload = useSetAtom(TimelineAtoms.mediaViewerPayload);
56	  const setImageInfoPayload = useSetAtom(TimelineAtoms.imageInfoPayload);
57	  const setVideoInfoPayload = useSetAtom(TimelineAtoms.videoInfoPayload);
58	
59	  const room = useMemo<RoomInterface | undefined>(() => {
60	    try {
61	      return MatrixCore.getRoom(payload.roomId);
62	    } catch {
63	      return undefined;
64	    }
65	  }, [payload.roomId]);
66	
67	  const { mediaItems, loading, reachedStart, paginationCount, loadMore } =
68	    useMediaTimeline({ room, roomId: payload.roomId });
69	
70	  /** Filtered events sorted newest-first. Falls back to the tapped event so
71	  the first frame isn't empty while the hook hydrates. */
72	  const events = useMemo<EventTimelineItem[]>(() => {
73	    const filtered = mediaItems.filter((item) => getMediaKind(item) !== null);
74	    return filtered.length === 0 ? [payload.initialEvent] : filtered;
75	  }, [mediaItems, payload.initialEvent]);
76	
77	  /** FlatList data: events + a trailing "older-edge" sentinel while more
78	  history remains. Swiping onto the sentinel triggers `loadMore`; incoming
79	  events land between the last real event and the sentinel, so the user
80	  slides from the spinner onto the newest item of the just-loaded batch.
81	  Suppressed during initial pagination so the seeded single-item render
82	  can't accidentally land on it. */
83	  const pages = useMemo<ViewerPage[]>(() => {
84	    const result: ViewerPage[] = events.map((event) => ({
85	      kind: "event",
86	      event,
87	    }));
88	    if (!loading && !reachedStart) result.push({ kind: "older-edge" });
89	    return result;
90	  }, [events, loading, reachedStart]);
91	
92	  /** Pages-index for the tapped event — resolved against the hydrated list. */
93	  const initialPageIndex = useMemo(() => {
94	    const idx = events.findIndex(
95	      (event) => getEventId(event) === payload.initialEventId,
96	    );
97	    return idx >= 0 ? idx : 0;
98	  }, [events, payload.initialEventId]);
99	
