105	    if (!currentEvent) return null;
106	    if (currentEvent.senderProfile.tag === ProfileDetails_Tags.Ready) {
107	      return (
108	        currentEvent.senderProfile.inner.displayName ?? currentEvent.sender
109	      );
110	    }
111	    return currentEvent.sender;
112	  }, [currentEvent]);
113	
114	  const formattedDate = useMemo(() => {
115	    if (!currentEvent) return null;
116	    return format(Number(currentEvent.timestamp), "MMM d, HH:mm");
117	  }, [currentEvent]);
118	
119	  const onClose = useCallback(() => {
120	    setPayload(null);
121	  }, [setPayload]);
122	
123	  const handleSingleTap = useCallback(() => {
124	    setShowControls((prev) => !prev);
125	  }, []);
126	
127	  const handleViewableItemsChanged = useCallback(
128	    ({ viewableItems }: { viewableItems: { index: number | null }[] }) => {
129	      const first = viewableItems[0];
130	      if (first?.index == null) return;
131	      setCurrentIndex(first.index);
132	    },
133	    [],
134	  );
135	
136	  const handleLocalUriChange = useCallback(
137	    (eventId: string | null, uri: string | null) => {
138	      if (!eventId) return;
139	      localUriByEventIdRef.current.set(eventId, uri);
140	    },
141	    [],
142	  );
143	
144	  const handleOpenInfo = useCallback(() => {
145	    if (!currentEvent) return;
146	    const eventId = getEventId(currentEvent);
147	    const localUri = eventId
148	      ? (localUriByEventIdRef.current.get(eventId) ?? null)
