190	              onLocalUriChange={onUriChange}
191	            />
192	          ) : kind === "video" ? (
193	            <MediaVideoPage
194	              event={event}
195	              isActive={index === currentIndex}
196	              onSingleTap={handleSingleTap}
197	              onLocalUriChange={onUriChange}
