    setLocalUri(null);
    setIsLoading(true);
    setHasError(false);
    const uri = await load();
    if (uri) setLocalUri(uri);
    else {
      setHasError(true);
      setIsLoading(false);
    }
  }, [load]);

  return (
    <Block
      width={SCREEN_WIDTH}
      height={SCREEN_HEIGHT}
      align="center"
      justify="center"
    >
      <Block width={videoSize.width} height={videoSize.height}>
        {isLoading && !hasError && (
          <Block
            absolute
            width={videoSize.width}
            height={videoSize.height}
            align="center"
