    setHasError(false);

    const load = async () => {
      try {
        if (isLocalUri(uri)) {
          setLocalUri(uri);
          return;
        }

        await cacheImage(uri);
        if (cancelled) return;
        setLocalUri(getCachedImagePathByURL(uri));
      } catch {
        if (cancelled) return;
        setIsLoading(false);
        setHasError(true);
      }
    };

    load();

    return () => {
      cancelled = true;
    };
  }, [uri]);

  const onClose = useCallback(() => {
    setPayload(null);
    setLocalUri(null);
    setHasError(false);
    setIsLoading(true);
    setShowControls(true);
  }, [setPayload]);

  const handleSingleTap = useCallback(() => {
    setShowControls((prev) => !prev);
  }, []);

  const handleImageLoad = useCallback(() => {
    setIsLoading(false);
    setHasError(false);
  }, []);

  const handleImageError = useCallback(() => {
    setIsLoading(false);
    setHasError(true);
  }, []);

  const handleRetry = useCallback(async () => {
    if (!uri) return;
    setLocalUri(null);
    setIsLoading(true);
    setHasError(false);

    try {
      if (isLocalUri(uri)) {
        setLocalUri(uri);
        return;
      }

      await cacheImage(uri);
      setLocalUri(getCachedImagePathByURL(uri));
    } catch {
      setIsLoading(false);
      setHasError(true);
    }
  }, [uri]);

  if (!visible) return null;

  return (
    <Modal
      visible={visible}
      animationType="fade"
      statusBarTranslucent
      transparent
      presentationStyle="overFullScreen"
      onRequestClose={onClose}
    >
      <Block
        background={Colors.black}
        flex={1}
        justify="center"
        align="center"
      >
        <Block
          absolute
          offsets={{ top: 0, left: 0, right: 0 }}
          zIndex={10}
          paddings={[56, 20, 16, 20]}
          flexDirection="row"
          align="center"
          justify="flex-end"
          gap={12}
          background={Colors.primary}
          animations={controlsAnimation.animations}
          pointerEvents={showControls ? "auto" : "none"}
        >
          <BlurGradientOverlay />
          <Block zIndex={2}>
            <Button.Wrapper onPress={onClose}>
              <Text font="InstrumentSans-Semibold" color={Colors.white}>
                Close
              </Text>
            </Button.Wrapper>
          </Block>
        </Block>

        <Block width={SCREEN_WIDTH} height={SCREEN_HEIGHT}>
          {isLoading && !hasError && (
            <Block
              absolute
              width={SCREEN_WIDTH}
              height={SCREEN_HEIGHT}
              align="center"
              justify="center"
              zIndex={5}
              background={Colors.white10}
            >
              <Loading isFullScreen={false} />
            </Block>
          )}

          {hasError ? (
            <Block
              width={SCREEN_WIDTH}
              height={SCREEN_HEIGHT}
              align="center"
              justify="center"
            >
              <Text color={Colors.white}>Failed to load image</Text>
              <TouchableOpacity
                onPress={handleRetry}
                style={styles.retryButton}
              >
                <Text size={TextSize.small} color={Colors.white}>
                  Tap to retry
                </Text>
              </TouchableOpacity>
            </Block>
          ) : localUri ? (
            <ImageZoom
              key={localUri}
              uri={localUri}
              minScale={1}
              maxScale={5}
              maxPanPointers={2}
              isPanEnabled
              isPinchEnabled
              isDoubleTapEnabled
              isSingleTapEnabled
              style={{ width: SCREEN_WIDTH, height: SCREEN_HEIGHT }}
              onLoad={handleImageLoad}
              onError={handleImageError}
              onSingleTap={handleSingleTap}
            />
          ) : null}
        </Block>
      </Block>
    </Modal>
  );
};

const styles = StyleSheet.create({
  image: {
    width: SCREEN_WIDTH,
    height: SCREEN_HEIGHT,
  },
  retryButton: {
    marginTop: 12,
    paddingVertical: 8,
    paddingHorizontal: 16,
  },
});

