31	    width: number;
32	    height: number;
33	  } | null>(null);
34	
35	  const videoSize = naturalSize
36	    ? (() => {
37	        const scale = Math.min(
38	          SCREEN_WIDTH / naturalSize.width,
39	          SCREEN_HEIGHT / naturalSize.height,
40	        );
41	        return {
42	          width: Math.round(naturalSize.width * scale),
43	          height: Math.round(naturalSize.height * scale),
44	        };
45	      })()
46	    : { width: SCREEN_WIDTH, height: SCREEN_HEIGHT };
47	
48	  const load = useCallback(async () => {
49	    if (!content) return null;
