import {
  BottomSheetModal,
  type BottomSheetModalProps,
} from "@gorhom/bottom-sheet";
import { animateSequence, Block } from "@prototyp/skeletor";
import {
  forwardRef,
  type ReactNode,
  useCallback,
  useEffect,
  useImperativeHandle,
  useRef,
} from "react";
import { Dimensions, StyleSheet } from "react-native";
import { usePreventSwipeBack } from "shared/hooks";
import { Colors } from "shared/styles";

const { height, width } = Dimensions.get("screen");

export interface AppBottomSheetRef {
  close: () => void;
}

interface Props {
  isOpen: boolean;
  children: ReactNode;
  maxContentSize?: number;
  enableContentPanningGesture?: boolean;
  keyboardBehavior?: BottomSheetModalProps["keyboardBehavior"];
  keyboardBlurBehavior?: BottomSheetModalProps["keyboardBlurBehavior"];
  android_keyboardInputMode?: BottomSheetModalProps["android_keyboardInputMode"];
  /** Skip the full-screen dim backdrop. Use when the host already provides
   *  its own dimmed background (e.g. sheet mounted inside an RN Modal). */
  hideBackdrop?: boolean;
  onClose: () => void;
}

export const AppBottomSheet = forwardRef<AppBottomSheetRef, Props>(
  (
    {
      isOpen,
      children,
      maxContentSize,
      enableContentPanningGesture,
      keyboardBehavior,
      keyboardBlurBehavior,
      android_keyboardInputMode,
      hideBackdrop,
      onClose,
    },
    ref,
  ) => {
    const sheetRef = useRef<BottomSheetModal>(null);
    const fadeIn = useRef(
      animateSequence({ opacity: [0, 1] }, { duration: 200 }),
    ).current;
    const isClosingRef = useRef(false);

    const handleDismiss = useCallback(() => {
      if (isClosingRef.current) return;
      isClosingRef.current = true;
      fadeIn.reverse(() => {
        isClosingRef.current = false;
        onClose();
      });
    }, [fadeIn, onClose]);

    useImperativeHandle(ref, () => ({
      close: () => {
        handleDismiss();
        sheetRef.current?.dismiss();
      },
    }));

    usePreventSwipeBack(isOpen);

    useEffect(() => {
      if (!isOpen) return;
      fadeIn.start();
      sheetRef.current?.present();
    }, [isOpen, fadeIn]);

    if (!isOpen) return null;

    const sheet = (
      <BottomSheetModal
        ref={sheetRef}
        handleStyle={styles.handle}
        handleIndicatorStyle={styles.handleIndicator}
        backgroundStyle={styles.background}
        enablePanDownToClose
        enableDynamicSizing
        maxDynamicContentSize={maxContentSize ?? height - 200}
        onDismiss={handleDismiss}
        enableContentPanningGesture={enableContentPanningGesture}
        keyboardBehavior={keyboardBehavior}
        keyboardBlurBehavior={keyboardBlurBehavior}
        android_keyboardInputMode={android_keyboardInputMode}
      >
        {children}
      </BottomSheetModal>
    );

    if (hideBackdrop) return sheet;

    return (
      <Block
        absolute
        width={width}
        height="100%"
        offsets={{ left: 0, top: 0 }}
        animations={fadeIn.animations}
        zIndex={9999}
        background={Colors.black70}
      >
        {sheet}
      </Block>
    );
  },
);

const styles = StyleSheet.create({
  background: {
    backgroundColor: Colors.blackMinus1,
    borderTopLeftRadius: 24,
    borderTopRightRadius: 24,
  },
  handle: {
    borderWidth: 1,
    borderBottomWidth: 0,
    borderTopLeftRadius: 24,
    borderTopRightRadius: 24,
    paddingHorizontal: 12,
    paddingTop: 12,
    paddingBottom: 24,
  },
  handleIndicator: {
    width: 84,
    height: 4,
    backgroundColor: Colors.white50,
  },
});

import { BottomSheetModalProvider } from "@gorhom/bottom-sheet";
import { animateParallel, Block, Text } from "@prototyp/skeletor";
import {
  type EventTimelineItem,
  ProfileDetails_Tags,
  type RoomInterface,
} from "@unomed/react-native-matrix-sdk";
import { format } from "date-fns";
import { useSetAtom } from "jotai";
import { MatrixCore } from "modules/matrix-client/services/MatrixCore";
import { getEventId } from "modules/matrix-client/utils";
import { TimelineAtoms } from "modules/timeline/jotai";
import {
  type FC,
  useCallback,
  useEffect,
  useMemo,
  useRef,
  useState,
} from "react";
import {
  FlatList,
  Image,
  Modal,
  StyleSheet,
  useWindowDimensions,
} from "react-native";
import { ImageInfoBottomSheet } from "screens/room/fragments/image-info-bottom-sheet";
import { VideoInfoBottomSheet } from "screens/room/fragments/video-info-bottom-sheet";
import { useMediaTimeline } from "screens/room-media/hooks";
import { Colors, TextSize } from "shared/styles";
import { BlurGradientOverlay } from "../blur-gradient-overlay";
import { Button } from "../button";
import { MediaEdgePage } from "./MediaEdgePage";
import { MediaImagePage } from "./MediaImagePage";
import { MediaVideoPage } from "./MediaVideoPage";
import { getMediaKind } from "./utils";

const OLDER_EDGE_KEY = "__older_edge__";

type ViewerPage =
  | { kind: "event"; event: EventTimelineItem }
  | { kind: "older-edge" };

interface Props {
  payload: MediaViewerPayload;
}

export const MediaViewerModalContent: FC<Props> = ({ payload }) => {
  const { width: SCREEN_WIDTH, height: SCREEN_HEIGHT } = useWindowDimensions();
  const [showControls, setShowControls] = useState(true);
  const [currentIndex, setCurrentIndex] = useState(0);
  const localUriByEventIdRef = useRef<Map<string, string | null>>(new Map());
  const controlsAnimation = useRef(
    animateParallel(
      { translateY: [-120, 0], opacity: [0, 1] },
      { duration: 280 },
    ),
  ).current;
  const setPayload = useSetAtom(TimelineAtoms.mediaViewerPayload);
  const setImageInfoPayload = useSetAtom(TimelineAtoms.imageInfoPayload);
  const setVideoInfoPayload = useSetAtom(TimelineAtoms.videoInfoPayload);

  const room = useMemo<RoomInterface | undefined>(() => {
    try {
      return MatrixCore.getRoom(payload.roomId);
    } catch {
      return undefined;
    }
  }, [payload.roomId]);

  const { mediaItems, loading, reachedStart, paginationCount, loadMore } =
    useMediaTimeline({ room, roomId: payload.roomId });

  /** Filtered events sorted newest-first. Falls back to the tapped event so
  the first frame isn't empty while the hook hydrates. */
  const events = useMemo<EventTimelineItem[]>(() => {
    const filtered = mediaItems.filter((item) => getMediaKind(item) !== null);
    return filtered.length === 0 ? [payload.initialEvent] : filtered;
  }, [mediaItems, payload.initialEvent]);

  /** FlatList data: events + a trailing "older-edge" sentinel while more
  history remains. Swiping onto the sentinel triggers `loadMore`; incoming
  events land between the last real event and the sentinel, so the user
  slides from the spinner onto the newest item of the just-loaded batch.
  Suppressed during initial pagination so the seeded single-item render
  can't accidentally land on it. */
  const pages = useMemo<ViewerPage[]>(() => {
    const result: ViewerPage[] = events.map((event) => ({
      kind: "event",
      event,
    }));
    if (!loading && !reachedStart) result.push({ kind: "older-edge" });
    return result;
  }, [events, loading, reachedStart]);

  /** Pages-index for the tapped event — resolved against the hydrated list. */
  const initialPageIndex = useMemo(() => {
    const idx = events.findIndex(
      (event) => getEventId(event) === payload.initialEventId,
    );
    return idx >= 0 ? idx : 0;
  }, [events, payload.initialEventId]);

  const currentPage = pages[currentIndex];
  const currentEvent = currentPage?.kind === "event" ? currentPage.event : null;
  const currentKind = currentEvent ? getMediaKind(currentEvent) : null;

  const senderName = useMemo(() => {
    if (!currentEvent) return null;
    if (currentEvent.senderProfile.tag === ProfileDetails_Tags.Ready) {
      return (
        currentEvent.senderProfile.inner.displayName ?? currentEvent.sender
      );
    }
    return currentEvent.sender;
  }, [currentEvent]);

  const formattedDate = useMemo(() => {
    if (!currentEvent) return null;
    return format(Number(currentEvent.timestamp), "MMM d, HH:mm");
  }, [currentEvent]);

  const onClose = useCallback(() => {
    setPayload(null);
  }, [setPayload]);

  const handleSingleTap = useCallback(() => {
    setShowControls((prev) => !prev);
  }, []);

  const handleViewableItemsChanged = useCallback(
    ({ viewableItems }: { viewableItems: { index: number | null }[] }) => {
      const first = viewableItems[0];
      if (first?.index == null) return;
      setCurrentIndex(first.index);
    },
    [],
  );

  const handleLocalUriChange = useCallback(
    (eventId: string | null, uri: string | null) => {
      if (!eventId) return;
      localUriByEventIdRef.current.set(eventId, uri);
    },
    [],
  );

  const handleOpenInfo = useCallback(() => {
    if (!currentEvent) return;
    const eventId = getEventId(currentEvent);
    const localUri = eventId
      ? (localUriByEventIdRef.current.get(eventId) ?? null)
      : null;
    if (currentKind === "image") {
      setImageInfoPayload({
        event: currentEvent,
        roomId: payload.roomId,
        localUri,
      });
    } else if (currentKind === "video") {
      setVideoInfoPayload({
        event: currentEvent,
        roomId: payload.roomId,
        localUri,
      });
    }
  }, [
    currentEvent,
    currentKind,
    payload.roomId,
    setImageInfoPayload,
    setVideoInfoPayload,
  ]);

  const keyExtractor = useCallback((page: ViewerPage) => {
    if (page.kind === "older-edge") return OLDER_EDGE_KEY;
    return getEventId(page.event) ?? "";
  }, []);

  const renderItem = useCallback(
    ({ item, index }: { item: ViewerPage; index: number }) => {
      if (item.kind === "older-edge") return <MediaEdgePage />;
      const event = item.event;
      const kind = getMediaKind(event);
      const eventId = getEventId(event);
      const onUriChange = (uri: string | null) =>
        handleLocalUriChange(eventId, uri);
      return (
        <Block width={SCREEN_WIDTH} height={SCREEN_HEIGHT}>
          {kind === "image" ? (
            <MediaImagePage
              event={event}
              onSingleTap={handleSingleTap}
              onLocalUriChange={onUriChange}
            />
          ) : kind === "video" ? (
            <MediaVideoPage
              event={event}
              isActive={index === currentIndex}
              onSingleTap={handleSingleTap}
              onLocalUriChange={onUriChange}
            />
          ) : null}
        </Block>
      );
    },
    [currentIndex, handleSingleTap, handleLocalUriChange],
  );

  const getItemLayout = useCallback(
    (_: ArrayLike<ViewerPage> | null | undefined, index: number) => ({
      length: SCREEN_WIDTH,
      offset: SCREEN_WIDTH * index,
      index,
    }),
    [SCREEN_WIDTH],
  );

  useEffect(() => {
    if (showControls) controlsAnimation.start();
    else controlsAnimation.reverse();
  }, [showControls]);

  // Keep paginating while on the sentinel until an image/video appears.
  // Re-fires on paginationCount so batches of only File/Audio items
  // automatically kick off the next fetch.
  useEffect(() => {
    if (currentPage?.kind === "older-edge" && !reachedStart) loadMore();
  }, [currentPage, reachedStart, paginationCount, loadMore]);

  return (
    <Modal
      visible
      animationType="fade"
      statusBarTranslucent
      transparent
      presentationStyle="overFullScreen"
      onRequestClose={onClose}
    >
      <BottomSheetModalProvider>
        <Block background={Colors.black} flex={1}>
          <FlatList
            data={pages}
            renderItem={renderItem}
            keyExtractor={keyExtractor}
            getItemLayout={getItemLayout}
            horizontal
            inverted={payload.source === "timeline"}
            pagingEnabled
            showsHorizontalScrollIndicator={false}
            initialScrollIndex={initialPageIndex}
            onViewableItemsChanged={handleViewableItemsChanged}
          />

          <Block
            absolute
            offsets={{ top: 0, left: 0, right: 0 }}
            zIndex={10}
            paddings={[56, 20, 16, 20]}
            flexDirection="row"
            align="center"
            justify="space-between"
            gap={12}
            background={Colors.primary}
            animations={controlsAnimation.animations}
            pointerEvents={showControls ? "auto" : "none"}
          >
            <BlurGradientOverlay />
            <Block width={60} align="flex-start" zIndex={2}>
              {!!currentEvent && (
                <Button.Wrapper onPress={handleOpenInfo}>
                  <Image
                    source={require("assets/icons/info.png")}
                    style={styles.infoIcon}
                    tintColor={Colors.white}
                  />
                </Button.Wrapper>
              )}
            </Block>
            <Block flex={1} align="center" gap={2} zIndex={2}>
              {senderName && (
                <Text
                  color={Colors.white}
                  font="InstrumentSans-Semibold"
                  numberOfLines={1}
                >
                  {senderName}
                </Text>
              )}
              {formattedDate && (
                <Text
                  size={TextSize.tiny}
                  color={Colors.white80}
                  numberOfLines={1}
                >
                  {formattedDate}
                </Text>
              )}
            </Block>
            <Block width={60} align="flex-end" zIndex={2}>
              <Button.Wrapper onPress={onClose}>
                <Text font="InstrumentSans-Semibold" color={Colors.white}>
                  Close
                </Text>
              </Button.Wrapper>
            </Block>
          </Block>
        </Block>
        <ImageInfoBottomSheet />
        <VideoInfoBottomSheet />
      </BottomSheetModalProvider>
    </Modal>
  );
};

const styles = StyleSheet.create({
  infoIcon: {
    width: 24,
    height: 24,
  },
});

import { ImageZoom } from "@likashefqet/react-native-image-zoom";
import { animateParallel, Block, Text } from "@prototyp/skeletor";
import { useAtom } from "jotai";
import { TimelineAtoms } from "modules/timeline/jotai";
import type { FC } from "react";
import { useCallback, useEffect, useRef, useState } from "react";
import {
  Modal,
  StyleSheet,
  TouchableOpacity,
  useWindowDimensions,
} from "react-native";
import { Colors, TextSize } from "shared/styles";
import {
  cacheImage,
  getCachedImagePathByURL,
} from "shared/utils/image-caching";
import { BlurGradientOverlay } from "../blur-gradient-overlay";
import { Button } from "../button";
import { Loading } from "../loading";

const isLocalUri = (uri: string) => uri.startsWith("file://");

export const ImageViewerModal: FC = () => {
  const { width: SCREEN_WIDTH, height: SCREEN_HEIGHT } = useWindowDimensions();
  const [payload, setPayload] = useAtom(TimelineAtoms.imageViewerPayload);
  const [localUri, setLocalUri] = useState<string | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [hasError, setHasError] = useState(false);
  const [showControls, setShowControls] = useState(true);
  const uri = payload?.uri ?? null;
  const visible = !!uri;

  const controlsAnimation = useRef(
    animateParallel(
      { translateY: [-120, 0], opacity: [0, 1] },
      { duration: 280 },
    ),
  ).current;

  useEffect(() => {
    if (showControls) controlsAnimation.start();
    else controlsAnimation.reverse();
  }, [showControls]);

  useEffect(() => {
    if (!uri) return;

    let cancelled = false;
    setLocalUri(null);
    setIsLoading(true);
    setHasError(false);

    const load = async () => {
      try {
        if (isLocalUri(uri)) {
          setLocalUri(uri);
          return;
        }

        await cacheImage(uri);
        if (cancelled) return;
        setLocalUri(getCachedImagePathByURL(uri));
      } catch {
        if (cancelled) return;
        setIsLoading(false);
        setHasError(true);
      }
    };

    load();

    return () => {
      cancelled = true;
    };
  }, [uri]);

  const onClose = useCallback(() => {
    setPayload(null);
    setLocalUri(null);
    setHasError(false);
    setIsLoading(true);
    setShowControls(true);
  }, [setPayload]);

  const handleSingleTap = useCallback(() => {
    setShowControls((prev) => !prev);
  }, []);

  const handleImageLoad = useCallback(() => {
    setIsLoading(false);
    setHasError(false);
  }, []);

  const handleImageError = useCallback(() => {
    setIsLoading(false);
    setHasError(true);
  }, []);

  const handleRetry = useCallback(async () => {
    if (!uri) return;
    setLocalUri(null);
    setIsLoading(true);
    setHasError(false);

    try {
      if (isLocalUri(uri)) {
        setLocalUri(uri);
        return;
      }

      await cacheImage(uri);
      setLocalUri(getCachedImagePathByURL(uri));
    } catch {
      setIsLoading(false);
      setHasError(true);
    }
  }, [uri]);

  if (!visible) return null;

  return (
    <Modal
      visible={visible}
      animationType="fade"
      statusBarTranslucent
      transparent
      presentationStyle="overFullScreen"
      onRequestClose={onClose}
    >
      <Block background={Colors.black} flex={1} justify="center" align="center">
        <Block
          absolute
          offsets={{ top: 0, left: 0, right: 0 }}
          zIndex={10}
          paddings={[56, 20, 16, 20]}
          flexDirection="row"
          align="center"
          justify="flex-end"
          gap={12}
          background={Colors.primary}
          animations={controlsAnimation.animations}
          pointerEvents={showControls ? "auto" : "none"}
        >
          <BlurGradientOverlay />
          <Block zIndex={2}>
            <Button.Wrapper onPress={onClose}>
              <Text font="InstrumentSans-Semibold" color={Colors.white}>
                Close
              </Text>
            </Button.Wrapper>
          </Block>
        </Block>

        <Block width={SCREEN_WIDTH} height={SCREEN_HEIGHT}>
          {isLoading && !hasError && (
            <Block
              absolute
              width={SCREEN_WIDTH}
              height={SCREEN_HEIGHT}
              align="center"
              justify="center"
              zIndex={5}
              background={Colors.white10}
            >
              <Loading isFullScreen={false} />
            </Block>
          )}

          {hasError ? (
            <Block
              width={SCREEN_WIDTH}
              height={SCREEN_HEIGHT}
              align="center"
              justify="center"
            >
              <Text color={Colors.white}>Failed to load image</Text>
              <TouchableOpacity
                onPress={handleRetry}
                style={styles.retryButton}
              >
                <Text size={TextSize.small} color={Colors.white}>
                  Tap to retry
                </Text>
              </TouchableOpacity>
            </Block>
          ) : localUri ? (
            <ImageZoom
              key={localUri}
              uri={localUri}
              minScale={1}
              maxScale={5}
              maxPanPointers={2}
              isPanEnabled
              isPinchEnabled
              isDoubleTapEnabled
              isSingleTapEnabled
              style={{ width: SCREEN_WIDTH, height: SCREEN_HEIGHT }}
              onLoad={handleImageLoad}
              onError={handleImageError}
              onSingleTap={handleSingleTap}
            />
          ) : null}
        </Block>
      </Block>
    </Modal>
  );
};

const styles = StyleSheet.create({
  retryButton: {
    marginTop: 12,
    paddingVertical: 8,
    paddingHorizontal: 16,
  },
});

import { ImageZoom } from "@likashefqet/react-native-image-zoom";
import { Block, Text } from "@prototyp/skeletor";
import type { EventTimelineItem } from "@unomed/react-native-matrix-sdk";
import { type FC, useCallback, useEffect, useState } from "react";
import {
  StyleSheet,
  TouchableOpacity,
  useWindowDimensions,
} from "react-native";
import { Colors, TextSize } from "shared/styles";
import { resolveEncryptedImage } from "shared/utils/encrypted-image-cache";
import { Loading } from "../loading";
import { getImageContent } from "./utils";

interface Props {
  event: EventTimelineItem;
  onSingleTap: () => void;
  onLocalUriChange: (uri: string | null) => void;
}

export const MediaImagePage: FC<Props> = ({
  event,
  onSingleTap,
  onLocalUriChange,
}) => {
  const { width: SCREEN_WIDTH, height: SCREEN_HEIGHT } = useWindowDimensions();
  const content = getImageContent(event);
  const [localUri, setLocalUri] = useState<string | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [hasError, setHasError] = useState(false);

  const load = useCallback(async () => {
    if (!content) {
      setHasError(true);
      setIsLoading(false);
      return null;
    }
    const mxcUrl = content.source.url();
    if (!mxcUrl) {
      setHasError(true);
      setIsLoading(false);
      return null;
    }
    try {
      const resolved = await resolveEncryptedImage({
        cacheKey: mxcUrl,
        mediaSource: content.source,
        mimeType: content.info?.mimetype || "image/jpeg",
      });
      return resolved ?? null;
    } catch {
      return null;
    }
  }, [content]);

  useEffect(() => {
    let cancelled = false;
    setLocalUri(null);
    setIsLoading(true);
    setHasError(false);

    load().then((uri) => {
      if (cancelled) return;
      if (uri) {
        setLocalUri(uri);
      } else {
        setHasError(true);
        setIsLoading(false);
      }
    });

    return () => {
      cancelled = true;
    };
  }, [load]);

  useEffect(() => {
    onLocalUriChange(localUri);
  }, [localUri, onLocalUriChange]);

  const handleImageLoad = useCallback(() => {
    setIsLoading(false);
    setHasError(false);
  }, []);

  const handleImageError = useCallback(() => {
    setIsLoading(false);
    setHasError(true);
  }, []);

  const handleRetry = useCallback(async () => {
    setLocalUri(null);
    setIsLoading(true);
    setHasError(false);
    const uri = await load();
    if (uri) {
      setLocalUri(uri);
    } else {
      setHasError(true);
      setIsLoading(false);
    }
  }, [load]);

  return (
    <Block width={SCREEN_WIDTH} height={SCREEN_HEIGHT}>
      {isLoading && !hasError && (
        <Block
          absolute
          width={SCREEN_WIDTH}
          height={SCREEN_HEIGHT}
          align="center"
          justify="center"
          zIndex={5}
          background={Colors.white10}
        >
          <Loading isFullScreen={false} />
        </Block>
      )}
      {hasError ? (
        <Block
          width={SCREEN_WIDTH}
          height={SCREEN_HEIGHT}
          align="center"
          justify="center"
        >
          <Text color={Colors.white}>Failed to load image</Text>
          <TouchableOpacity onPress={handleRetry} style={styles.retryButton}>
            <Text size={TextSize.small} color={Colors.white}>
              Tap to retry
            </Text>
          </TouchableOpacity>
        </Block>
      ) : localUri ? (
        <ImageZoom
          key={localUri}
          uri={localUri}
          minScale={1}
          maxScale={5}
          maxPanPointers={2}
          isPanEnabled
          isPinchEnabled
          isDoubleTapEnabled
          isSingleTapEnabled
          style={{ width: SCREEN_WIDTH, height: SCREEN_HEIGHT }}
          onLoad={handleImageLoad}
          onError={handleImageError}
          onSingleTap={onSingleTap}
        />
      ) : null}
    </Block>
  );
};

const styles = StyleSheet.create({
  retryButton: {
    marginTop: 12,
    paddingVertical: 8,
    paddingHorizontal: 16,
  },
});

import { Block, Text } from "@prototyp/skeletor";
import type { EventTimelineItem } from "@unomed/react-native-matrix-sdk";
import { type FC, useCallback, useEffect, useState } from "react";
import { TouchableWithoutFeedback, useWindowDimensions } from "react-native";
import Video, { type OnLoadData } from "react-native-video";
import { Button } from "shared/components/button";
import { Colors, TextSize } from "shared/styles";
import { resolveEncryptedVideo } from "shared/utils/encrypted-video-cache";
import { Loading } from "../loading";
import { getVideoContent } from "./utils";

interface Props {
  event: EventTimelineItem;
  isActive: boolean;
  onSingleTap: () => void;
  onLocalUriChange: (uri: string | null) => void;
}

export const MediaVideoPage: FC<Props> = ({
  event,
  isActive,
  onSingleTap,
  onLocalUriChange,
}) => {
  const { width: SCREEN_WIDTH, height: SCREEN_HEIGHT } = useWindowDimensions();
  const content = getVideoContent(event);
  const [localUri, setLocalUri] = useState<string | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [hasError, setHasError] = useState(false);
  const [naturalSize, setNaturalSize] = useState<{
    width: number;
    height: number;
  } | null>(null);

  const videoSize = naturalSize
    ? (() => {
        const scale = Math.min(
          SCREEN_WIDTH / naturalSize.width,
          SCREEN_HEIGHT / naturalSize.height,
        );
        return {
          width: Math.round(naturalSize.width * scale),
          height: Math.round(naturalSize.height * scale),
        };
      })()
    : { width: SCREEN_WIDTH, height: SCREEN_HEIGHT };

  const load = useCallback(async () => {
    if (!content) return null;
    const mxcUrl = content.source.url();
    const mimeType = content.info?.mimetype || "video/mp4";
    if (!mxcUrl) return null;
    try {
      return await resolveEncryptedVideo({
        cacheKey: mxcUrl,
        mediaSource: content.source,
        mimeType,
      });
    } catch {
      return null;
    }
  }, [content]);

  useEffect(() => {
    if (!isActive || localUri) return;
    let cancelled = false;
    setIsLoading(true);
    setHasError(false);

    load().then((uri) => {
      if (cancelled) return;
      if (uri) {
        setLocalUri(uri);
      } else {
        setHasError(true);
        setIsLoading(false);
      }
    });

    return () => {
      cancelled = true;
    };
  }, [isActive, localUri, load]);

  useEffect(() => {
    onLocalUriChange(localUri);
  }, [localUri, onLocalUriChange]);

  const handleVideoLoad = useCallback((data: OnLoadData) => {
    setIsLoading(false);
    setHasError(false);
    setNaturalSize({
      width: data.naturalSize.width,
      height: data.naturalSize.height,
    });
  }, []);

  const handleVideoError = useCallback(() => {
    setIsLoading(false);
    setHasError(true);
  }, []);

  const handleRetry = useCallback(async () => {
    setLocalUri(null);
    setIsLoading(true);
    setHasError(false);
    const uri = await load();
    if (uri) setLocalUri(uri);
    else {
      setHasError(true);
      setIsLoading(false);
    }
  }, [load]);

  return (
    <Block
      width={SCREEN_WIDTH}
      height={SCREEN_HEIGHT}
      align="center"
      justify="center"
    >
      <Block width={videoSize.width} height={videoSize.height}>
        {isLoading && !hasError && (
          <Block
            absolute
            width={videoSize.width}
            height={videoSize.height}
            align="center"
            justify="center"
            zIndex={5}
            background={Colors.white10}
          >
            <Loading isFullScreen={false} />
          </Block>
        )}
        {hasError ? (
          <Block
            width={videoSize.width}
            height={videoSize.height}
            align="center"
            justify="center"
          >
            <Text color={Colors.white}>Failed to load video</Text>
            <Button.Wrapper onPress={handleRetry}>
              <Text size={TextSize.small} color={Colors.white}>
                Tap to retry
              </Text>
            </Button.Wrapper>
          </Block>
        ) : localUri ? (
          <TouchableWithoutFeedback onPress={onSingleTap}>
            <Video
              source={{
                uri: localUri,
                type: content?.info?.mimetype || "video/mp4",
              }}
              style={{ width: videoSize.width, height: videoSize.height }}
              resizeMode="contain"
              controls
              paused={!isActive}
              onLoad={handleVideoLoad}
              onError={handleVideoError}
            />
          </TouchableWithoutFeedback>
        ) : null}
      </Block>
    </Block>
  );
};

import { Block } from "@prototyp/skeletor";
import type { FC } from "react";
import { useWindowDimensions } from "react-native";
import { Colors } from "shared/styles";
import { Loading } from "../loading";

export const MediaEdgePage: FC = () => {
  const { width, height } = useWindowDimensions();
  return (
    <Block
      background={Colors.black}
      align="center"
      justify="center"
      width={width}
      height={height}
    >
      <Loading isFullScreen={false} />
    </Block>
  );
};

